    U3.typeById = id => U3.DATA_TYPES.find(t => t.id === id) || null;

    /* 自动判定：根据"有没有地区列 / 有没有年份列 / 个体是否跨年重复"给建议 */
    U3.autoDetectType = function (o) {
        const hasId = !!o.hasId, hasYear = !!o.hasYear, sameId = !!o.sameId;
        if (hasId && hasYear && sameId) return 'panel';
        if (hasId && hasYear && !sameId) return 'pooled';
        if (!hasId && hasYear) return 'ts';
        if (hasId && !hasYear) return 'cross';
        return null;
    };

